"lead": "Respuesta corta: deflactar es subir los tramos del IRPF al ritmo de la inflación, para que una subida de sueldo que solo compensa precios no te haga pagar un tipo más alto. Feijóo lo planteó como prioridad el 5 de octubre de 2026 (según la prensa).",
